*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:"Trebuchet MS",Verdana,sans-serif}button,input,select{font:inherit}a{color:inherit;text-underline-offset:4px}button{cursor:pointer;color:var(--ink);border:1px solid var(--ink);background:transparent;min-height:44px;padding:10px 16px;border-radius:3px}button:hover{background:#e0e7d8}button:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid var(--coral);outline-offset:4px}button[aria-pressed=true]{background:var(--ink);color:var(--paper)}.wrap{max-width:1320px;padding:28px 4vw 48px;margin:auto}.top{display:flex;align-items:center;justify-content:space-between;padding-bottom:20px;border-bottom:2px solid var(--ink);gap:14px}.brand{font-family:Georgia,serif;font-size:26px;font-weight:bold;letter-spacing:-1px}.eyebrow{font:12px "Courier New",monospace;letter-spacing:2px;text-transform:uppercase}.hero{display:grid;grid-template-columns:1.3fr 1fr;gap:30px;align-items:end;padding:44px 0 30px}h1{font-family:Georgia,serif;font-size:clamp(50px,7.5vw,104px);font-weight:normal;line-height:.93;letter-spacing:-4px;margin:12px 0 24px}h1 em{color:var(--coral)}.intro{max-width:420px;font-size:17px;line-height:1.65;margin:0 0 12px}.stamp{display:inline-block;border:2px solid var(--coral);color:var(--coral);padding:8px 14px;transform:rotate(-5deg);font:13px "Courier New",monospace;font-weight:bold}.bench{display:grid;grid-template-columns:minmax(0,1fr) 330px;border:1px solid var(--ink);box-shadow:7px 7px 0 #d3d9c9}.stage{padding:25px;position:relative;overflow:hidden;background-color:#e8e9d9;background-image:linear-gradient(#193b3809 1px,transparent 1px),linear-gradient(90deg,#193b3809 1px,transparent 1px);background-size:24px 24px;display:flex;flex-direction:column}.stage-head{display:flex;justify-content:space-between;gap:12px;align-items:center}.small{font:12px "Courier New",monospace}.stage svg{width:100%;height:auto;display:block;flex:1;min-height:220px;m