<script>
const $=id=>document.getElementById(id);
const parts=['upper','toe','heel','sole','laces'];
const presets=[
{name:'Mint Condition',colours:['#a9d2be','#f5ecd8','#d94432','#f5ecd8','#193b38']},
{name:'Platform Sunshine',colours:['#e7ad35','#f5ecd8','#243c59','#f5ecd8','#243c59']},
{name:'Forest Disco',colours:['#b5a2cd','#e4d8eb','#285a48','#e5a4b3','#285a48']}
];
let state={name:presets[0].name,colours:[...presets[0].colours]},history=[];
function remember(){history.push(JSON.parse(JSON.stringify(state)));if(history.length>60)history.shift()}
function render(){parts.forEach((part,i)=>document.documentElement.style.setProperty('--'+part,state.colours[i]));$('name').value=state.name;$('design-title').textContent=state.name||'Untitled colourway';sync();$('undo').disabled=!history.length}
function sync(){const i=parts.indexOf($('panel').value);$('colour').value=state.colours[i];$('hex').value=state.colours[i].toUpperCase()}
function paint(colour){const i=parts.indexOf($('panel').value);if(state.colours[i]===colour)return;remember();state.colours[i]=colour;render();$('status').textContent=$('panel').selectedOptions[0].text.split(' /')[0]+' painted '+colour.toUpperCase()+'.'}
['#a9d2be','#d94432','#f5ecd8','#193b38','#e7ad35','#243c59','#b5a2cd','#285a48','#e5a4b3','#ffffff','#ef7954','#8eadaf'].forEach(colour=>{const b=document.createElement('button');b.className='swatch';b.style.setProperty('--swatch',colour);b.setAttribute('aria-label','Paint selected panel '+colour);b.title=colour;b.onclick=()=>paint(colour);$('palette').append(b)});
$('panel').onchange=sync;
$('colour').addEventListener('change',e=>paint(e.target.value));
$('name').addEventListener('change',e=>{remember();state.name=e.target.value;render()});
$('name').addEventListener('input',e=>$('design-title').textContent=e.target.value||'Untitled colourway');
document.querySelectorAll('[data-part]').forEach(el=>el.addEventListener('click',()=>{$('panel').value=el.dataset.part;sync();$('status').textContent='Editing '+el.dataset.part+'. Choose a paint below.'}));
document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{remember();const p=presets[+b.dataset.preset];state={name:p.name,colours:[...p.colours]};render();$('status').textContent=p.name+' loaded. Now give it your own twist.'});
$('undo').onclick=()=>{if(history.length){state=history.pop();render();$('status').textContent='Last change undone.'}};
$('reset').onclick=()=>{remember();state={name:presets[0].name,colours:[...presets[0].colours]};render();$('status').textContent='Fresh mint. Start again.'};
$('flip').onclick=()=>{const b=$('flip'),on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',on);$('shoe-wrap').classList.toggle('flip',on)};
$('export').onclick=async()=>{
 const button=$('export');button.disabled=true;
 try{
 const svg=$('shoe').cloneNode(true);
 svg.setAttribute('xmlns','http://www.w3.org/2000/svg');
 svg.querySelectorAll('*').forEach(el=>{for(const attr of ['fill','stroke']){const v=el.getAttribute(attr);if(v&&v.includes('var(')){const key=v.match(/--([a-z]+)/)[1];el.setAttribute(attr,state.colours[parts.indexOf(key)])}}});
 const style=document.createElementNS('http://www.w3.org/2000/svg','style');style.textContent='.shoe-base{stroke:#193b38;stroke-width:2.4;stroke-linejoin:round}';svg.prepend(style);
 const blob=new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml'}),url=URL.createObjectURL(blob);
 const img=new Image();
 await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});
 const canvas=document.createElement('canvas');canvas.width=1400;canvas.height=1000;const ctx=canvas.getContext('2d');
 ctx.fillStyle='#f5f0e5';ctx.fillRect(0,0,1400,1000);ctx.fillStyle='#193b38';ctx.font='bold 38px Georgia';ctx.fillText('Sole Studio.',80,95);
 ctx.font='18px monospace';ctx.fillText('ONE OF ONE / MADE BY YOU',80,135);
 ctx.drawImage(img,30,135,1340,720);URL.revokeObjectURL(url);
 ctx.font='46px Georgia';ctx.fillText(state.name||'Untitled colourway',80,855,1230);
 state.colours.forEach((c,i)=>{ctx.fillStyle=c;ctx.fillRect(80+i*70,905,48,30);ctx.strokeStyle='#193b38';ctx.strokeRect(80+i*70,905,48,30)});
 ctx.fillStyle='#193b38';ctx.font='17px monospace';ctx.fillText('AN ENTIRELY IMAGINARY SNEAKER',680,927);
 const png=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!png)throw Error('Export unavailable');
 const download=URL.createObjectURL(png),a=document.createElement('a');a.href=download;a.download='sole-studio-'+(state.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')||'custom')+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(download),30000);
 $('status').textContent='Design card ready! Check your downloads. On mobile, open it to save or share.';
 }catch(e){$('status').textContent='The card could not export in this browser. You can still take a screenshot of your design.'}finally{button.disabled=false}
};
render();
</script></body></html>
